def check(rxn, xyz):
    """Stereocentres outside the reaction centre keep their reactant handedness (sign of signed volume)."""
    nb = rxn.neighbours('reactant')
    checked = 0

    def vol(c, ns, X):
        if len(ns) >= 4:
            o = X[ns[3]]
            a, b, d = X[ns[0]] - o, X[ns[1]] - o, X[ns[2]] - o
        else:
            o = X[c]
            a, b, d = X[ns[0]] - o, X[ns[1]] - o, X[ns[2]] - o
        return float(np.dot(a, np.cross(b, d)))

    for c in range(rxn.n):
        if rxn.reactant_chiral_tags[c] not in (1, 2) or c in rxn.reaction_centre:
            continue
        ns = list(nb.get(c, []))
        if len(ns) < 3:
            continue
        ns = ns[:4]
        v_r = vol(c, ns, rxn.reactant_xyz)
        if abs(v_r) < 0.3:
            continue
        checked += 1
        v_t = vol(c, ns, xyz)
        if v_t * v_r < 0 and abs(v_t) > 0.4:
            return False, (f"stereocentre {rxn.symbols[c]}{c + 1} inverted: signed volume "
                           f"{v_r:.2f} in reactant vs {v_t:.2f} in TS")
    if checked == 0:
        return True, "rule not applicable"
    return True, f"{checked} spectator stereocentre(s) keep their handedness"

def check(rxn, xyz):
    """Product stereocentres have the same handedness (signed volume sign) in the TS as in the product."""
    nb = rxn.neighbours('product')
    centres = [i for i in range(rxn.n) if rxn.product_chiral_tags[i] in (1, 2)]

    def vol(c, pos, ns):
        v = []
        for k in ns[:3]:
            d = pos[k] - pos[c]
            v.append(d / (np.linalg.norm(d) + 1e-9))
        return float(np.dot(v[0], np.cross(v[1], v[2])))

    checked = 0
    for c in centres:
        ns = nb.get(c, [])
        if len(ns) < 3:
            continue
        ref = vol(c, rxn.product_xyz, ns)
        if abs(ref) < 0.1:
            continue
        ts = vol(c, xyz, ns)
        checked += 1
        # centres in the reaction centre may legitimately be near-planar at the TS
        thr = 0.3 if c in rxn.reaction_centre else 0.15
        if ts * ref < 0 and abs(ts) > thr:
            return False, (f"{rxn.symbols[c]}{c + 1} has inverted handedness vs product "
                           f"(signed volume {ts:+.2f} at TS, {ref:+.2f} in product)")
    if checked == 0:
        return True, "rule not applicable"
    return True, f"{checked} product stereocentre(s) have product handedness"

def check(rxn, xyz):
    """Atom pairs never bonded in reactant or product are not closer than a minimum contact distance."""
    bonded = set(rxn.reactant_bonds) | set(rxn.product_bonds)
    n = rxn.n
    if n < 2:
        return True, "rule not applicable"
    d = np.linalg.norm(xyz[:, None, :] - xyz[None, :, :], axis=2)
    heavy = rxn.atoms != 1
    worst = None
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in bonded:
                continue
            if heavy[i] and heavy[j]:
                lim = 1.55
            elif heavy[i] or heavy[j]:
                lim = 1.15
            else:
                lim = 1.05
            ratio = d[i, j] / lim
            if ratio < 1.0 and (worst is None or ratio < worst[0]):
                worst = (ratio, i, j, lim)
    if worst is not None:
        _, i, j, lim = worst
        return False, (f"non-bonded {rxn.symbols[i]}{i + 1}-{rxn.symbols[j]}{j + 1} "
                       f"is {d[i, j]:.2f} A apart (minimum {lim:.2f} A)")
    return True, "no non-bonded pair is unrealistically close"

