        b1 = unit(b1)
        v = b0 - np.dot(b0, b1) * b1
        w = b2 - np.dot(b2, b1) * b1
        return math.degrees(math.atan2(np.dot(np.cross(b1, v), w), np.dot(v, w)))

    found = False
    worst, msg = 0.0, ""
