    for (i, j) in dbl:
        if i in centre or j in centre:
            continue
        # skip cumulated systems (allenes, ketenes): torsion is ill-defined
        if any(o == 2 for k, o in rb.items() if k != (i, j) and (i in k or j in k) and
               ((k[0] in (i, j)) and (k[1] in (i, j))) is False and False):
            continue
        ci = sum(1 for k, o in rb.items() if o == 2 and i in k)
        cj = sum(1 for k, o in rb.items() if o == 2 and j in k)
        if ci > 1 or cj > 1:
            continue
        si = [a for a in nb[i] if a != j and a in npd[i] and a not in centre]
        sj = [b for b in nb[j] if b != i and b in npd[j] and b not in centre]
