def check(rxn, xyz):
    """Each forming/breaking bond is stretched at least ~10% beyond its reactant/product bonded length."""
    if not rxn.changed_bonds:
        return True, "rule not applicable"
    best = None
    for (i, j) in rxn.changed_bonds:
        i, j = min(i, j), max(i, j)
        refs = []
        if (i, j) in rxn.reactant_bonds:
            refs.append(float(np.linalg.norm(rxn.reactant_xyz[i] - rxn.reactant_xyz[j])))
        if (i, j) in rxn.product_bonds:
            refs.append(float(np.linalg.norm(rxn.product_xyz[i] - rxn.product_xyz[j])))
        if not refs:
            continue
        ref = max(refs)
        d = float(np.linalg.norm(xyz[i] - xyz[j]))
        ratio = d / ref
        if best is None or ratio > best[0]:
            best = (ratio, i, j, d, ref)
    if best is None:
        return True, "rule not applicable"
    ratio, i, j, d, ref = best
    if ratio < 1.10:
        return False, (f"most stretched changing bond {rxn.symbols[i]}{i + 1}-{rxn.symbols[j]}{j + 1} "
                       f"is {d:.2f} A vs bonded {ref:.2f} A (ratio {ratio:.2f} < 1.10)")
    return True, (f"{rxn.symbols[i]}{i + 1}-{rxn.symbols[j]}{j + 1} stretched to "
                  f"{d:.2f} A (ratio {ratio:.2f})")

def check(rxn, xyz):
    """Each forming/breaking bond is partway between reactant and product lengths, and breaking and forming progress are balanced."""
    brk, frm = [], []
    for (i, j) in rxn.changed_bonds:
        rr = float(np.linalg.norm(rxn.reactant_xyz[i] - rxn.reactant_xyz[j]))
        rp = float(np.linalg.norm(rxn.product_xyz[i] - rxn.product_xyz[j]))
        rt = float(np.linalg.norm(xyz[i] - xyz[j]))
        span = rp - rr
        if abs(span) < 0.4:
            continue
        f = (rt - rr) / span
        label = f"{rxn.symbols[i]}{i + 1}-{rxn.symbols[j]}{j + 1}"
        if f < -0.3 or f > 1.4:
            return False, f"{label} TS length {rt:.2f} A (reactant {rr:.2f}, product {rp:.2f}) gives progress {f:.2f}"
        if (i, j) in rxn.reactant_bonds and (i, j) not in rxn.product_bonds:
            brk.append(f)
        elif (i, j) in rxn.product_bonds and (i, j) not in rxn.reactant_bonds:
            frm.append(f)
    if not brk or not frm:
        if not brk and not frm:
            return True, "rule not applicable"
        return True, "single-sided bond change, per-bond progress within range"
    sb, sf = sum(brk), sum(frm)
    if abs(sb - sf) > 1.5:
        return False, f"unbalanced progress: breaking sum {sb:.2f} vs forming sum {sf:.2f}"
    return True, f"progress balanced: breaking {sb:.2f}, forming {sf:.2f}"

